#!/usr/bin/env python3
import sys
from bs4 import BeautifulSoup

def remove_javascript(html_file):
    """Remove JavaScript from HTML to prevent XSS attacks."""
    with open(html_file, 'r', encoding='utf-8') as f:
        html_content = f.read()

    soup = BeautifulSoup(html_content, 'html.parser')

    # Remove all script tags
    for script in soup.find_all('script'):
        script.decompose()

    # Remove all event handler attributes
    event_handlers = {
        'onclick', 'onload', 'onerror', 'onmouseover', 'onmouseout',
        'onkeydown', 'onkeyup', 'onchange', 'onsubmit', 'onfocus',
        'onblur', 'onmousemove', 'onmouseenter', 'onmouseleave',
        'ondblclick', 'oncontextmenu', 'onwheel', 'onscroll',
        'ontouchstart', 'ontouchend', 'ontouchcancel', 'ontouchmove',
        'onpaste', 'oncopy', 'oncut', 'ondrag', 'ondrop',
    }

    for tag in soup.find_all(True):
        for attr in list(tag.attrs.keys()):
            if attr.lower() in event_handlers:
                del tag.attrs[attr]

    # Remove javascript: URLs from attributes
    for tag in soup.find_all(True):
        for attr in list(tag.attrs.keys()):
            value = tag.attrs[attr]
            if isinstance(value, str) and value.strip().lower().startswith('javascript:'):
                del tag.attrs[attr]

    # Write back to file preserving original formatting
    with open(html_file, 'w', encoding='utf-8') as f:
        f.write(str(soup))

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python filter.py <html_file>")
        sys.exit(1)

    remove_javascript(sys.argv[1])

